class IdempotencyStore:
    def __init__(self):
        self._records = {}

    def execute(self, key, fingerprint, operation):
        if not key:
            raise ValueError("missing idempotency key")
        if key in self._records:
            saved_fp, saved_result = self._records[key]
            if saved_fp != fingerprint:
                raise ValueError("idempotency key reused with different request")
            return saved_result, False
        result = operation()
        self._records[key] = (fingerprint, result)
        return result, True

store = IdempotencyStore()
count = {"n": 0}
def operation():
    count["n"] += 1
    return {"transaction":"tx-1"}

first, created1 = store.execute("k1", "amount=10", operation)
second, created2 = store.execute("k1", "amount=10", operation)
assert first == second
assert created1 is True and created2 is False
assert count["n"] == 1
try:
    store.execute("k1", "amount=999", operation)
except ValueError:
    pass
else:
    raise AssertionError("conflicting reuse was not rejected")
print("Idempotency behavior verified.")

from pathlib import Path
import json
import re

def inspect_repo(root: Path):
    findings=[]
    forbidden_names={'.env', 'id_rsa', 'credentials.json'}
    assignment=re.compile(r'^[A-Z0-9_]*(SECRET|TOKEN|PASSWORD|API_KEY)[A-Z0-9_]* *= *[^$]+$')
    for path in root.rglob('*'):
        if not path.is_file() or '.git' in path.parts:
            continue
        if path.name in forbidden_names:
            findings.append({"path":str(path.relative_to(root)),"rule":"forbidden-secret-file"})
        if path.suffix in {'.env', '.ini', '.cfg'} or path.name.endswith('.env.example'):
            text=path.read_text(encoding='utf-8', errors='ignore')
            for line_no,line in enumerate(text.splitlines(), 1):
                if assignment.match(line) and not re.search(r'\$\{|<|CHANGE_ME|EXAMPLE', line):
                    findings.append({"path":str(path.relative_to(root)),"line":line_no,"rule":"secret-like-assignment"})
    return findings

